Templates.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/testimonials.ListView */}}
{{/* Starting point generated by WebThings: every field of the data is used below. */}}
<main id="content">
    <h1>{{.Title}}</h1>
    {{range .Testimonials}}
        <article>
            {{/* ID: {{.ID}} — stable, usable as an anchor */}}
            {{with .Quote}}<p>{{.}}</p>{{end}}
            {{with .Author}}<p>{{.}}</p>{{end}}
            {{with .Role}}<p>{{.}}</p>{{end}}
            {{with .Organisation}}<p>{{.}}</p>{{end}}
            {{if .PhotoURL}}<img src="{{.PhotoURL}}"{{with .PhotoSrcset}} srcset="{{.}}" sizes="100vw"{{end}} alt="">{{end}}
            {{/* PhotoOriginalURL: {{.PhotoOriginalURL}} — the uploaded file, for a download link */}}
        </article>
    {{end}}
</main>

Types.Decl:
type APITestimonial struct {
	ID           string     `json:"id"`
	Quote        string     `json:"quote"`
	Author       string     `json:"author"`
	Role         string     `json:"role"`
	Organisation string     `json:"organisation"`
	Photo        *api.Image `json:"photo"`
	// URL is the page that lists the testimonials, null while the instance
	// is on no page; testimonials have no page of their own. APIURL is the
	// testimonial in the API.
	URL       *string   `json:"url"`
	APIURL    string    `json:"api_url"`
	UpdatedAt time.Time `json:"updated_at"`
}

type Fields struct {
	Photo  string `db:"photo_id,null"`
	Author string `db:"author"`
}

type ListView struct {
	// Title is the title of the page the module is mounted on.
	Title        string
	Testimonials []Testimonial
}

type Service struct {
	// contains unexported fields
}

type Testimonial struct {
	ID           string
	Quote        string
	Author       string
	Role         string
	Organisation string
	// PhotoURL is the photo as pages show it, at most media.ImageWidth
	// wide (see frontend.Frontend.Image); PhotoSrcset lists smaller
	// copies for a srcset attribute, PhotoWidth and PhotoHeight are the
	// size of PhotoURL and PhotoOriginalURL is the uploaded file, for
	// downloads. All are empty when the testimonial has no photo.
	PhotoURL         string
	PhotoSrcset      string
	PhotoOriginalURL string
	PhotoWidth       int
	PhotoHeight      int
}

type Text struct {
	Quote        string `db:"quote"`
	Role         string `db:"author_role"`
	Organisation string `db:"organisation"`
}
